package com.alpharip.staffmod.BuildTimelapse;
import com.alpharip.staffmod.BuildTimelapse.core.*;import com.alpharip.staffmod.BuildTimelapse.camera.*;import com.alpharip.staffmod.BuildTimelapse.capture.*;import com.alpharip.staffmod.BuildTimelapse.timeline.*;import com.alpharip.staffmod.BuildTimelapse.analytics.*;import com.alpharip.staffmod.BuildTimelapse.effects.*;import com.alpharip.staffmod.BuildTimelapse.export.*;
/** Composition root for the independent studio services. Runtime adapters are injected. */
public final class BuildTimelapse {private final BuildTimelapseProject project;private final CameraController camera;private final CaptureService capture;private final Timeline timeline;private final BuildActivityTracker activity;private final EffectsController effects;private final ExportQueue exports;private final BuildTimelapseController controller;
 public BuildTimelapse(BuildTimelapseProject p,CameraController c,CaptureService s,Timeline t,BuildActivityTracker a,EffectsController e,ExportQueue q,ProjectStore store){if(p==null||c==null||s==null||t==null||a==null||e==null||q==null||store==null)throw new IllegalArgumentException("All studio services are required");project=p;camera=c;capture=s;timeline=t;activity=a;effects=e;exports=q;controller=new BuildTimelapseController(p,c,s,t,store);}
 public BuildTimelapseProject getProject(){return project;}public CameraController getCamera(){return camera;}public CaptureService getCapture(){return capture;}public Timeline getTimeline(){return timeline;}public BuildActivityTracker getActivity(){return activity;}public EffectsController getEffects(){return effects;}public ExportQueue getExports(){return exports;}public BuildTimelapseController getController(){return controller;}
}
